package org.json;import java.util.*;public class JSONObject {public static Map<String,JSONObject> registry=new HashMap<>();public Map<String,Object> data=new HashMap<>();public JSONObject(){}public JSONObject(String s){if("{}".equals(s))return;JSONObject o=registry.get(s);if(o==null)throw new IllegalArgumentException("Invalid mock JSON");data=o.data;}public JSONObject put(String k,Object v){data.put(k,v);return this;}public JSONArray optJSONArray(String k){return (JSONArray)data.get(k);}public JSONObject optJSONObject(String k){return (JSONObject)data.get(k);}public String optString(String k){return (String)data.getOrDefault(k,"");}public Iterator<String> keys(){return data.keySet().iterator();}}